package com.neonshift.app;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.file.*;
public class ReceiptStoreTest{
 static int n;static void check(boolean value){n++;if(!value)throw new AssertionError("check "+n);}interface Run{void run()throws Exception;}static void bad(Run r)throws Exception{try{r.run();throw new AssertionError("invalid accepted");}catch(IllegalArgumentException expected){n++;}}
 public static void main(String[]args)throws Exception{
  Context context=new Context();ReceiptStore store=new ReceiptStore(context);String id=ReceiptStore.id(),file=id+".img";Files.write(store.attachment(file).toPath(),"original bytes".getBytes());JSONObject value=new JSONObject().put("id",id).put("merchant","Example Hardware").put("date","2026-11-26").put("currency","AUD").put("category","materials").put("total","20.00").put("workPercent","50").put("tax","1.82").put("file",file).put("sha256","example").put("rawText","Original receipt text").put("items",new JSONArray().put(new JSONObject().put("name","Gloves").put("description","Work gloves").put("amount","20.00")));
  bad(()->store.save(value));store.saveDraft(value);check(store.draft().getString("file").equals(file));value.put("reviewed",true);JSONObject saved=store.save(value);check(saved.getString("businessTotal").equals("10.00"));check(store.summaries().length()==1);check(!store.summaries().getJSONObject(0).has("rawText"));check(!store.summaries().getJSONObject(0).has("items"));check(store.get(id).getJSONArray("items").getJSONObject(0).getString("name").equals("Gloves"));check(store.duplicate("example").equals(id));check(store.draft().length()==0);
  ReceiptStore reopened=new ReceiptStore(context);check(reopened.get(id).getString("rawText").equals("Original receipt text"));value.put("total","25.50").put("reimbursable",true).put("reimbursed",true);reopened.save(value);check(reopened.summaries().length()==1);check(reopened.get(id).getString("businessTotal").equals("12.75"));reopened.setDeleted(id,true);check(reopened.get(id).getBoolean("deleted"));check(reopened.duplicate("example").isEmpty());JSONObject copy=new JSONObject(value.toString()).put("id",ReceiptStore.id());reopened.save(copy);bad(()->reopened.setDeleted(id,false));reopened.setDeleted(copy.getString("id"),true);check(new String(Files.readAllBytes(reopened.attachment(file).toPath())).equals("original bytes"));reopened.setDeleted(id,false);check(!reopened.get(id).getBoolean("deleted"));
  bad(()->reopened.attachment("../../private.txt"));bad(()->reopened.get("../private"));JSONObject wrong=new JSONObject(value.toString()).put("workPercent","101");bad(()->reopened.save(wrong));final JSONObject nan=new JSONObject(value.toString()).put("total","NaN");bad(()->reopened.save(nan));JSONObject foreign=new JSONObject(value.toString()).put("currency","XYZ");bad(()->reopened.save(foreign));JSONObject invalidItem=new JSONObject(value.toString());invalidItem.getJSONArray("items").getJSONObject(0).put("name","");bad(()->reopened.save(invalidItem));JSONObject negative=new JSONObject(value.toString()).put("total","-1");bad(()->reopened.save(negative));
  System.out.println("PASS: "+n+" receipt persistence, review, edits, work share, duplicate, restore, attachment and validation checks.");
 }
}
